// План specs/stripe-connect.md 1.2 + 1.3 (кейсы .qa/tests/stripe-connect/SC-04, SC-05). Только Pre-Prod (Stripe test mode), десктоп Chrome, EN.
// #06a307 Stripe Connect:
//   1.2 — оплата по Payment Link картой 4242: на Stripe Checkout продавец — Connect-аккаунт компании (не Techory), платёж Succeeded в Payment Portal;
//   1.3 — Payment Portal → Refund (confirm + alert) → Refunded в портале и в работе, остаток вернулся.
// @writes @data @stripe-test: работа «QA-AUTO pay connect … #06a307» с позицией $5.NN (уникальная сумма — чтобы найти строку в портале),
// ссылка, платёж и возврат (test mode). Порядок важен (serial): 1.3 возвращает платёж из 1.2. Очистка в afterAll: работа → Cancelled.
// На prod (app.techory.ai) — пропуск: реальная оплата.
// Имя продавца на Checkout берётся из профиля Stripe-аккаунта компании (решение пользователя 12.11, context.md): у TTP Test Locks это
// «Contract Test Locksmith» — переопределить QA_CONNECT_SELLER (например, для компании, зарегистрированной через Connect со своим названием).
// Не сверено с сайтом при записи (правило проекта — тесты только пишутся): адрес Payment Portal (/Payments), формат суммы в портале
// с центами, роль строк Recent Transactions (таблица). Разметка — по скриншотам 06a307-v2-step8*, step9*.
import { test, expect, BrowserContext, Dialog, Page } from '@playwright/test';
import {
  CLIENT, IS_PROD, PREPROD, amountRe, blockMessaging, cancelJob, createJobWithBalance, createPaymentLink, escRe,
  expectPayPage, historyRow, jobNumber, openCustomerContext, openPaymentsTab, openRoleContext, payOnStripeCheckout, pp,
} from '../job-payments/payments-helpers';

const SELLER = process.env.QA_CONNECT_SELLER || 'Contract Test Locksmith';
const NOW = Date.now();
const CENTS = `${1 + (Math.floor(NOW / 9) % 9)}${1 + (NOW % 9)}`; // 11–99, без 0 — сумма в портале без «$5.1»-сокращений

const PRICE = `5.${CENTS}`;
const AMOUNT = `$${PRICE}`;
const portalAmountRe = new RegExp(`\\$${escRe(PRICE)}(?!\\d)`);

test.describe('Stripe Connect: link payment and refund (#06a307)', () => {
  test.describe.configure({ mode: 'serial' });
  test.skip(IS_PROD, 'оплата и возврат Stripe test — только Pre-Prod');

  let context: BrowserContext;
  let page: Page;
  let jobUrl: string | null = null;
  let messaging: string[] = [];

  test.beforeAll(async ({ browser }, testInfo) => {
    testInfo.setTimeout(180_000);
    ({ context, page } = await openRoleContext(browser, testInfo));
    messaging = await blockMessaging(page);
    jobUrl = await createJobWithBalance(page, 'connect', { price: PRICE, ticket: '#06a307' });
  });

  test.afterAll(async () => {
    expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
    await cancelJob(page, jobUrl);
    await context?.close();
  });

  test('QA-AUTO: payment link paid with Stripe test 4242 — Checkout seller is the company Connect account, Succeeded in Payment Portal #06a307 @desktop @writes @data @stripe-test', async ({ browser }, testInfo) => {
    test.setTimeout(240_000);
    await openPaymentsTab(page, jobUrl!);
    const jobNo = await jobNumber(page);
    const link = await createPaymentLink(page);
    expect(link).toMatch(new RegExp(`^${escRe(PREPROD)}/pay\\?t=`));

    const customer = await openCustomerContext(browser, testInfo);
    try {
      await customer.page.goto(link);
      await expectPayPage(customer.page, AMOUNT, jobNo);
      await customer.page.getByRole('button', { name: `Pay ${AMOUNT}` }).click();

      // Stripe Checkout: продавец — Connect-аккаунт компании, не платформа (комментарий 11.10: в чеке имя бизнеса мастера)
      await customer.page.waitForURL(/checkout\.stripe\.com/, { timeout: 30_000 });
      await expect(customer.page.getByText(`Pay ${SELLER}`, { exact: true })).toBeVisible({ timeout: 30_000 });
      await expect(customer.page.getByText(/^Pay Techory/)).toHaveCount(0);
      await expect(customer.page.getByText(`Job ${jobNo}`, { exact: true })).toBeVisible();

      await payOnStripeCheckout(customer.page);
      await customer.page.waitForURL(new RegExp(`^${escRe(PREPROD)}/pay\\?.*paid=1`), { timeout: 90_000 });
      await expect(customer.page.getByText('Payment received', { exact: true })).toBeVisible();
    } finally {
      await customer.context.close();
    }

    // Payment Portal: строка клиента с этой суммой — Succeeded (статус приходит из Stripe — ждём с перезагрузкой)
    await expect(async () => {
      await openPortal(page);
      await expect(portalRow(page, 'Succeeded')).not.toHaveCount(0, { timeout: 5_000 });
    }).toPass({ timeout: 90_000 });
    await expect(portalRow(page, 'Succeeded').first().getByRole('button', { name: 'Refund' })).toBeVisible();

    // Работа: Credit Card Ref pi_… Completed
    await expect(async () => {
      await openPaymentsTab(page, jobUrl!);
      await expect(historyRow(page, /Ref: pi_/).filter({ hasText: 'Completed' })).toHaveCount(1, { timeout: 5_000 });
    }).toPass({ timeout: 90_000 });
  });

  test('QA-AUTO: Refund from Payment Portal — confirm, «The payment was refunded.», Refunded in portal and job, remaining restored #06a307 @desktop @writes @data @stripe-test', async () => {
    test.setTimeout(180_000);
    await openPortal(page);
    const row = portalRow(page, 'Succeeded').first();
    await expect(row).toBeVisible();

    // confirm «Refund this payment in full?…» → OK; alert «The payment was refunded.» (комментарий 11.10: Refund полный)
    const messages: string[] = [];
    const onDialog = async (d: Dialog) => { messages.push(`${d.type()}: ${d.message()}`); await d.accept(); };
    page.on('dialog', onDialog);
    try {
      await row.getByRole('button', { name: 'Refund' }).click();
      await expect.poll(() => messages.join('\n'), { timeout: 60_000 }).toContain('The payment was refunded.');
    } finally {
      page.off('dialog', onDialog);
    }
    expect(messages[0], 'подтверждение перед возвратом').toMatch(/^confirm: Refund this payment in full\?/);

    // Портал: строка — Refunded, кнопки Refund нет
    await expect(async () => {
      await openPortal(page);
      await expect(portalRow(page, 'Refunded')).not.toHaveCount(0, { timeout: 5_000 });
    }).toPass({ timeout: 60_000 });
    await expect(portalRow(page, 'Refunded').first().getByRole('button', { name: 'Refund' })).toHaveCount(0);

    // Работа: Credit Card Ref pi_… — Refunded, Amount Paid $0.00, Remaining to pay = сумма работы
    await expect(async () => {
      await openPaymentsTab(page, jobUrl!);
      await expect(historyRow(page, /Ref: pi_/).filter({ hasText: 'Refunded' })).toHaveCount(1, { timeout: 5_000 });
    }).toPass({ timeout: 90_000 });
    const main = page.getByRole('main');
    await expect(main.getByText(/^Amount Paid:/).locator('..')).toContainText('$0.00');
    await expect(main.getByText(`Remaining to pay: ${AMOUNT}`, { exact: true }).first()).toBeVisible();
    await expect(main.getByText(amountRe(AMOUNT)).first()).toBeVisible();
  });
});

/** Payment Portal (меню Payments). */
async function openPortal(page: Page) {
  await page.goto(pp('/Payments'));
  await expect(page.getByRole('heading', { name: 'Payment Portal' })).toBeVisible({ timeout: 30_000 });
}

/** Строка Recent Transactions: клиент TTP Customer, сумма этого теста, статус. */
function portalRow(page: Page, status: 'Succeeded' | 'Refunded') {
  return page.getByRole('main').getByRole('row')
    .filter({ hasText: CLIENT })
    .filter({ hasText: portalAmountRe })
    .filter({ hasText: status });
}
